(function () {
  "use strict";
  const host = document.getElementById("carte-maroc");
  if (!host) return;
  const AR = document.documentElement.lang === "ar";
  const R = window.CMS_REGIONS;
  const L = AR
    ? { me: "مقاولون صغار تمت مواكبتهم", amc: "جمعيات القروض الصغرى الشريكة", agr: "مشاريع صغيرة ممولة (الأنشطة المدرة للدخل)", cap: "مركز الجهة", todo: "يُستكمل", hint: "اختر جهة على الخريطة", region: "الجهة" }
    : { me: "Micro-entrepreneurs accompagnés", amc: "Associations de microcrédit partenaires", agr: "Micro-projets AGR financés", cap: "Chef-lieu", todo: "À compléter", hint: "Sélectionnez une région sur la carte", region: "Région" };
  const NS = "http://www.w3.org/2000/svg";
  const fmt = new Intl.NumberFormat(AR ? "ar-MA" : "fr-FR", { numberingSystem: "latn" });
  const max = Math.max(0, ...R.map(r => r.me || 0));

  const svg = document.createElementNS(NS, "svg");
  svg.setAttribute("viewBox", "0 0 520 620");
  svg.setAttribute("class", "map__svg");
  svg.setAttribute("role", "group");
  svg.setAttribute("aria-label", AR ? "خريطة جهات المملكة الاثنتي عشرة" : "Carte des 12 régions du Royaume");
  const gShapes = document.createElementNS(NS, "g");
  const gLabels = document.createElementNS(NS, "g");
  gLabels.setAttribute("class", "map__labels");
  gLabels.setAttribute("aria-hidden", "true");
  svg.append(gShapes, gLabels);

  const els = {};
  R.forEach(r => {
    const p = document.createElementNS(NS, "path");
    p.setAttribute("d", r.d);
    p.setAttribute("class", "map__region");
    p.setAttribute("tabindex", "0");
    p.setAttribute("role", "button");
    p.setAttribute("aria-label", (AR ? r.ar : r.fr));
    if (max && r.me) p.style.setProperty("--k", (0.35 + 0.65 * r.me / max).toFixed(2));
    p.addEventListener("click", () => select(r.id));
    p.addEventListener("keydown", e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); select(r.id); } });
    gShapes.append(p);
    const c = document.createElementNS(NS, "circle");
    c.setAttribute("cx", r.c[0]); c.setAttribute("cy", r.c[1]); c.setAttribute("r", 11);
    const t = document.createElementNS(NS, "text");
    t.setAttribute("x", r.c[0]); t.setAttribute("y", r.c[1] + 4); t.textContent = r.n;
    gLabels.append(c, t);
    els[r.id] = p;
  });
  host.append(svg);

  // Region list
  const list = document.getElementById("carte-liste");
  R.forEach(r => {
    const b = document.createElement("button");
    b.type = "button"; b.className = "map__item"; b.dataset.id = r.id;
    b.innerHTML = `<span class="map__num">${r.n}</span>${AR ? r.ar : r.fr}`;
    b.addEventListener("click", () => select(r.id));
    list.append(b);
  });

  const panel = document.getElementById("carte-panel");
  const val = v => (v == null ? `<span class="map__todo">${L.todo}</span>` : fmt.format(v));
  function select(id) {
    const r = R.find(x => x.id === id);
    Object.values(els).forEach(e => e.classList.remove("is-active"));
    els[id].classList.add("is-active");
    els[id].parentNode.append(els[id]); // bring to front
    list.querySelectorAll(".map__item").forEach(b => b.classList.toggle("is-active", b.dataset.id === id));
    panel.innerHTML = `
      <p class="eyebrow">${L.region} ${r.n} / 12</p>
      <h3>${AR ? r.ar : r.fr}</h3>
      <p class="map__cap">${L.cap} : <strong>${AR ? r.car : r.cfr}</strong></p>
      <dl class="map__stats">
        <div><dt>${L.me}</dt><dd>${val(r.me)}</dd></div>
        <div><dt>${L.amc}</dt><dd>${val(r.amc)}</dd></div>
        <div><dt>${L.agr}</dt><dd>${val(r.agr)}</dd></div>
      </dl>`;
  }
  select("MA-06");
})();
